:root {
  --color-text: #172033;
  --color-surface: #ffffff;
  --color-action-primary: #1457c5;
  --space-control: 0.75rem;
  --radius-control: 0.625rem;
}

.button-primary {
  color: white;
  background: var(--color-action-primary);
  border-radius: var(--radius-control);
  padding: var(--space-control) 1rem;
}

type ButtonProps = {
  variant?: "primary" | "secondary" | "danger";
  loading?: boolean;
  disabled?: boolean;
  children: React.ReactNode;
};

function Button({ variant = "primary", loading = false, disabled = false, children }: ButtonProps) {
  return (
    <button className={`button button--${variant}`} disabled={disabled || loading}>
      {loading ? "Loading…" : children}
    </button>
  );
}

