type FieldProps = {
  id: string;
  label: string;
  value: string;
  onChange: (value: string) => void;
  helpText?: string;
  error?: string;
};

export function Field({ id, label, value, onChange, helpText, error }: FieldProps) {
  const helpId = `${id}-help`;
  const errorId = `${id}-error`;
  const describedBy = [helpText ? helpId : null, error ? errorId : null]
    .filter(Boolean).join(' ') || undefined;
  return (
    <div>
      <label htmlFor={id}>{label}</label>
      <input id={id} value={value}
        onChange={(event) => onChange(event.target.value)}
        aria-invalid={Boolean(error)} aria-describedby={describedBy} />
      {helpText && <p id={helpId}>{helpText}</p>}
      {error && <p id={errorId} role="alert">{error}</p>}
    </div>
  );
}

